def choose_move(observation):
    grid_w = observation.get("grid_width", 0)
    grid_h = observation.get("grid_height", 0)

    pos = observation.get("self_position", {})
    ex = pos.get("x", 0)
    ey = pos.get("y", 0)

    opp = observation.get("opponent_position", {})
    ox = opp.get("x", 0)
    oy = opp.get("y", 0)

    # Default: stay
    best = [0, 0]

    # Simple heuristic: move away from opponent if adjacent
    dx = ex - ox
    dy = ey - oy
    if abs(dx) <= 1 and abs(dy) <= 1:
        if dx != 0:
            best[0] = 1 if dx < 0 else -1
        if dy != 0:
            best[1] = 1 if dy < 0 else -1
        return best

    # If resources present, move toward nearest resource
    res = observation.get("resources", [])
    if isinstance(res, list) and res:
        best_r = None
        best_d = None
        for r in res:
            rx = r.get("x")
            ry = r.get("y")
            if rx is None or ry is None:
                continue
            d = abs(rx - ex) + abs(ry - ey)
            if best_d is None or d < best_d:
                best_d = d
                best_r = (rx, ry)
        if best_r is not None and best_d is not None and best_d > 0:
            if best_r[0] > ex:
                best[0] = 1
            elif best_r[0] < ex:
                best[0] = -1
            if best_r[1] > ey:
                best[1] = 1
            elif best_r[1] < ey:
                best[1] = -1
            return best

    # Try to move toward center if no other info
    cx = grid_w // 2
    cy = grid_h // 2
    if ex < cx:
        best[0] = 1
    elif ex > cx:
        best[0] = -1
    if ey < cy:
        best[1] = 1
    elif ey > cy:
        best[1] = -1
    return best
